const offlineSource = document.documentElement.hasAttribute("data-offline") ? "<!doctype html>\n" + document.documentElement.outerHTML : null;
const $=s=>document.querySelector(s);
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=k=>({'<Esc>':'Esc','<Enter>':'↵',' ':'Space','<BS>':'⌫','<C-r>':'Ctrl+r'}[k]||k);
const keyHTML=k=>`<kbd>${escapeHTML(label(k))}</kbd>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('vim-fieldwork-v1')||'{}')}catch{}
let done=new Set(Array.isArray(saved.done)?saved.done:[]), demoTimer=null, appended=Number.isSafeInteger(saved.position)&&saved.position>=0?saved.position:0;

function persist(){try{localStorage.setItem('vim-fieldwork-v1',JSON.stringify({done:[...done],position:Math.max(0,appended-1)}))}catch{}}
// Character-level LCS keeps unrelated text unmarked, including repeated edits.
function rawDiff(a,b){const dp=Array.from({length:a.length+1},()=>new Uint16Array(b.length+1));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i][j]=a[i]===b[j]?1+dp[i+1][j+1]:Math.max(dp[i+1][j],dp[i][j+1]);const removed=new Set(),added=new Set();let i=0,j=0;while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&a[i]===b[j]){i++;j++}else if(i<a.length&&(j===b.length||dp[i+1][j]>=dp[i][j+1]))removed.add(i++);else added.add(j++)}return {removed,added}}
function diff(a,b){let start=0,end=0;while(start<a.length&&start<b.length&&a[start]===b[start])start++;while(end<a.length-start&&end<b.length-start&&a[a.length-1-end]===b[b.length-1-end])end++;const d=rawDiff(a.slice(start,a.length-end),b.slice(start,b.length-end));return {removed:new Set([...d.removed].map(i=>i+start)),added:new Set([...d.added].map(i=>i+start))}}
function codeHTML(text,marks,kind){let offset=0;return text.split('\n').map((line,i)=>{const start=offset;offset+=line.length+1;return `<div class="snippet-line"><span class="line-no">${i+1}</span><span>${[...line].map((c,j)=>marks.has(start+j)?`<mark class="${kind}">${c===' '?'␣':escapeHTML(c)}</mark>`:c===' '&&(line[j+1]===' '||line[j-1]===' '||j===line.length-1)?'<span class="visible-space">␣</span>':escapeHTML(c)).join('')||' '}${marks.has(start+line.length)&&i<text.split('\n').length-1?`<mark class="${kind}" title="Line break">↵</mark>`:''}</span></div>`}).join('')}
const titles=['Delete one extra “p”.','Change “cat” to “bat”.','Put “hello ” before “world”.','Add “!” at the end.','Add a task between these two lines.','Delete “very ”.','Delete the first three words.','Change the first comma to a colon.','Delete the comment.','Put “# ” at the start.','Change “cold” to “hot”.','Change the text inside the quotes.','Empty the parentheses.','Remove “(optional)”.','Replace the items inside the brackets.','Delete the DEBUG line.','Copy “la la la” onto a new line.','Swap the first two lines.','Join these two lines.','Replace the whole line with “done”.','Change “blue” to “green”.','Change both “cold” words to “warm”.','Change the second “cat” to “dog”.','Change every “red” to “blue”.','Delete everything before the semicolon.','Make “quiet” UPPERCASE.','Delete the first two lines.','Copy “reusable” below “finish”.','Put “- ” at the start of every line.','Change both quoted values to “ready”.'];
function appendCard(){const seq=appended++,id=seq<missions.length?seq:(seq*17)%missions.length,m=missions[id],changes=diff(m.before,m.after);if(id===0){changes.removed.clear();changes.removed.add(2)}const card=document.createElement('article');card.className='challenge-card';card.id=`edit-${seq}`;card.innerHTML=`<div class="card-eyebrow"><span>EDIT THIS TEXT</span><span class="completed"></span></div><h2>${escapeHTML(titles[id])}</h2><div class="comparison"><section><div class="snippet-label">BEFORE <span>Remove the marked text</span></div><div class="snippet">${codeHTML(m.before,changes.removed,'removed')}</div></section><div class="compare-arrow" aria-hidden="true">→</div><section><div class="snippet-label">AFTER <span>This is your goal</span></div><div class="snippet">${codeHTML(m.after,changes.added,'added')}</div></section></div><div class="space-note">${[8,13].includes(id)?'␣ means a space. Keep the spaces shown in the target.':'Red = remove. Green = add. Everything else stays the same. ␣ = space.'}</div><div class="practice"><div class="panel-head"><span>YOUR TURN · EDIT HERE</span><button class="text-button reset">↺ Start over</button></div><div class="live-editor"></div><div class="status"><span class="mode">NORMAL</span><span class="cursor"></span><span>Esc = Normal mode</span></div><div class="trail"><span>YOUR KEYS</span><div class="keys"><span class="placeholder">Type in the editor above</span></div><span class="key-count">0 keys</span></div><div class="first-tip" ${id===0?'':'hidden'}>The cursor is on the extra <strong>p</strong>. Press <kbd>x</kbd> to delete it. Then check your edit.</div><div class="actions"><button class="quiet hint">Show a hint</button><button class="primary check">Check my edit ↗</button></div><div class="hint-box" hidden></div><div class="result" aria-live="polite"></div></div><button class="skip text-button">Next edit →</button>`;
 if(!changes.removed.size)card.querySelector('.snippet-label span').textContent='Start with this text';
 $('#challenge-feed').replaceChildren(card);let editor=null,keys=[],submitted=false;
 const q=s=>card.querySelector(s);function renderKeys(){q('.keys').innerHTML=keys.length?keys.slice(-70).map(keyHTML).join(''):'<span class="placeholder">Type in the editor above</span>';q('.key-count').textContent=`${keys.length} ${keys.length===1?'key':'keys'}`}
 function reset(){CodeMirror.Vim.handleKey(editor,'<Esc>');editor.setValue(m.before);editor.setCursor(...m.cursor);editor.clearHistory();keys=[];submitted=false;q('.result').innerHTML='';q('.hint-box').hidden=true;renderKeys();editor.focus()}
 function start(){if(editor){editor.focus();return}editor=CodeMirror(q('.live-editor'),{value:m.before,keyMap:'vim',lineNumbers:true,tabSize:2,indentUnit:2,viewportMargin:Infinity});editor.setCursor(...m.cursor);editor.getInputField().setAttribute('aria-label',`Edit: ${titles[id]}`);editor.setOption('extraKeys',{Tab:c=>{if(c.state.vim.insertMode)c.replaceSelection('  ');else q('.hint').focus()}});editor.on('vim-mode-change',e=>q('.mode').textContent=e.mode.toUpperCase());editor.on('cursorActivity',()=>{const p=editor.getCursor();q('.cursor').textContent=`Line ${p.line+1}, column ${p.ch+1}`});editor.on('change',()=>{submitted=false;q('.result').innerHTML=''});editor.getWrapperElement().addEventListener('keydown',e=>{if(['Shift','Control','Alt','Meta','CapsLock'].includes(e.key)||e.metaKey||(e.key==='Tab'&&!editor.state.vim.insertMode))return;keys.push(e.key==='Escape'?'<Esc>':e.key==='Enter'?'<Enter>':e.key==='Backspace'?'<BS>':e.ctrlKey?`<C-${e.key}>`:e.key);renderKeys()},true);editor.refresh();editor.focus()}
 function next(){editor.getInputField().blur();appendCard();persist();window.scrollTo({top:0,behavior:'instant'})}
 q('.skip').onclick=next;q('.reset').onclick=reset;q('.hint').onclick=()=>{q('.hint-box').hidden=!q('.hint-box').hidden;q('.hint-box').textContent=m.hint};
 q('.check').onclick=()=>{const value=editor.getValue();if(value!==m.after){const delta=diff(value,m.after);q('.result').innerHTML=`<div class="feedback error"><h3>Here’s what still needs to change.</h3><div class="comparison"><section><div class="snippet-label">YOUR TEXT</div><div class="snippet">${codeHTML(value,delta.removed,'removed')}</div></section><div class="compare-arrow">→</div><section><div class="snippet-label">TARGET</div><div class="snippet">${codeHTML(m.after,delta.added,'added')}</div></section></div><p>Remove the red text. Add the green text. <small>␣ = space · ↵ = line break</small></p></div>`;return}submitted=true;done.add(id);persist();q('.completed').textContent='✓ Done';q('.result').innerHTML=`<div class="feedback"><div class="success-label">✓ THAT’S IT. EXACT MATCH.</div><h3>Here’s the Vim way.</h3><div class="solution">${m.keys.map(keyHTML).join('')}</div><p>${escapeHTML(m.why)}</p><p class="score">Your attempt: ${keys.length} ${keys.length===1?'key':'keys'} · This route: ${m.keys.length} ${m.keys.length===1?'key':'keys'}</p><div class="feedback-actions"><button class="quiet watch">▷ Watch it happen</button><button class="primary next">Next edit →</button></div></div>`;q('.watch').onclick=()=>demo(m);q('.next').onclick=next};start();return card}
appendCard();persist();
if(offlineSource){$('#download').addEventListener('click',e=>{e.preventDefault();const url=URL.createObjectURL(new Blob([offlineSource],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vim-fieldwork.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}

function feed(editor,sequence,step){let command=null;for(const key of sequence){if(command!==null){if(key==='<Enter>'){if(command[0]===':')CodeMirror.Vim.handleEx(editor,command.slice(1));else{CodeMirror.Vim.handleKey(editor,'/');const inp=editor.getWrapperElement().querySelector('.CodeMirror-dialog input');inp.value=command.slice(1);inp.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,which:13,bubbles:true}));}command=null}else command+=key;continue}if((key===':'||key==='/')&&sequence[0]===key&&!editor.state.vim.insertMode){command=key;continue}if(editor.state.vim.insertMode&&!key.startsWith('<')){editor.replaceSelection(key);CodeMirror.signal(editor,'inputRead',editor,{text:[key],origin:'+input'})}else CodeMirror.Vim.handleKey(editor,key);if(step)step(key)}}
function demo(m){clearTimeout(demoTimer);$('#modal-title').textContent='One edit, step by step.';$('#modal-body').innerHTML='<div id="demo"></div><div class="demo-keys">'+m.keys.map(keyHTML).join('')+'</div><p class="modal-note">'+escapeHTML(m.why)+'</p><button class="quiet" id="again">Replay ↺</button>';$('#modal').showModal();const d=CodeMirror($('#demo'),{value:m.before,keyMap:'vim',lineNumbers:true,readOnly:false,tabSize:2});d.setCursor(...m.cursor);let n=0;function tick(){if(!$('#modal').open)return;n++;d.setValue(m.before);CodeMirror.Vim.handleKey(d,'<Esc>');d.setCursor(...m.cursor);feed(d,m.keys.slice(0,n));document.querySelectorAll('.demo-keys kbd').forEach((k,i)=>k.classList.toggle('played',i<n));if(n<m.keys.length)demoTimer=setTimeout(tick,360)}demoTimer=setTimeout(tick,450);$('#again').onclick=()=>{clearTimeout(demoTimer);n=0;tick()};setTimeout(()=>d.refresh(),0)}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>clearTimeout(demoTimer));$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$('#reference').onclick=()=>{$('#modal-title').textContent='Your pocket reference';$('#modal-body').innerHTML=`<p class="modal-note">Normal mode is home. Press Escape to get back. Combine an operator with a motion or a text object: <kbd>c</kbd> + <kbd>iw</kbd> = change this word.</p><div class="ref-grid">${[
['Move','h j k l — left, down, up, right','w / b / e — next word / back / word end','0 / ^ / $ — line start / content start / end','gg / G — first / last line','f{char} / t{char} — find / stop before'],
['Edit','i / a — insert before / after','I / A — insert at start / end','o / O — new line below / above','x / r{char} — delete / replace character','u / Ctrl+r — undo / redo'],
['Compose','d / c / y — delete / change / yank','iw / aw — inner word / around word','i" / i( / i[ — inside delimiters','dd / cc / yy — operate on whole line','p / P — put after / before'],
['Go further','v / V — visual / visual line mode','/text then Enter — search; n repeats','* — next occurrence of current word','. — repeat the last change','qa … q / @a — record / play macro']].map(r=>`<section><h3>${r[0]}</h3>${r.slice(1).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</section>`).join('')}</div><p class="modal-note">Click the editor to capture keys. Tab in Normal mode moves focus to the buttons. A physical keyboard works best. This is a browser Vim sandbox powered by CodeMirror, with original exercises.</p>`;$('#modal').showModal()};

window.runCourseTests=()=>{const node=document.createElement('div');document.body.append(node);const test=CodeMirror(node,{keyMap:'vim'});const results=missions.map(m=>{CodeMirror.Vim.handleKey(test,'<Esc>');test.setValue(m.before);test.setCursor(...m.cursor);try{feed(test,m.keys);return {title:m.title,pass:test.getValue()===m.after,actual:test.getValue(),expected:m.after}}catch(e){return {title:m.title,pass:false,error:String(e)}}});node.remove();return results};
if(location.search.includes('selftest')){const results=runCourseTests();const pre=document.createElement('pre');pre.id='test-results';pre.textContent=JSON.stringify(results,null,2);document.body.prepend(pre)}
